// Studio kit v4, splash: copied by `npm run kit`, never edit it here.
// Studio kit, embedded tool "splash": the Musclor Duck Games opening, the same in every game.
// Embedded (copied into the game by `npm run kit`), because it plays while the game starts and offline in the app.
// The source lives in games-catalog/tools/splash/ (drawing: build.py, code: splash.src.js): never edit a copy,
// nor public/kit/embed/splash.js, which `python3 tools/splash/build.py` writes.
//
// Load it with a plain <script> (not async), before the game scripts. It covers the page with the opening
// (an egg falls and hatches, the duck appears, its shadow grows into a strongman, the title lands), then fades
// away and removes itself. The game loads underneath meanwhile and is never blocked:
//   GameSplash.done      a promise, resolved when the opening is gone (wait for it to start music or a menu intro)
//   GameSplash.playing   true while it is on screen
//   GameSplash.skip()    ends it now; a tap on it does the same
// The event "musclor-splash:done" is sent on window at the same moment.
// Shown once per session (the first page opened; ?splash=on shows it again), not in the GDD preview
// (?tuning=preview) nor with ?splash=off. kit.json may set "splash": false to keep the
// tool copied but silent. With "reduce motion" on the device, the finished picture is shown still, then fades.
// Never breaks a game: if the pictures cannot be read, it leaves at once.
(function(){
  'use strict';
  var KIT={"id":"evolia","android":"com.zed69000.evolia"};
  var q=new URLSearchParams(location.search);
  if(window.GameSplash)return;
  // Once per session: a game made of several pages (menu, then the game) shows it at the first one only.
  var seen=false;
  try{seen=sessionStorage.getItem("musclor_splash")==="1"&&q.get("splash")!=="on";}catch(e){}
  if(KIT.splash===false||q.get("splash")==="off"||q.get("tuning")==="preview"||seen){
    window.GameSplash={playing:false,duration:0,done:Promise.resolve(),skip:function(){}};
    return;
  }
  try{sessionStorage.setItem("musclor_splash","1");}catch(e){}
  var M={"W":1086,"H":1448,"eyes":[[393,662,11,18],[346,672,13,20]],"items":{"mticks":{"x":132,"y":95,"w":207,"h":211,"ax":0,"ay":702},"dticks":{"x":146,"y":544,"w":104,"h":122,"ax":483,"ay":915},"duck":{"x":113,"y":558,"w":351,"h":339,"ax":794,"ay":0},"m0":{"x":104,"y":912,"w":217,"h":217,"ax":1355,"ay":0},"m1":{"x":316,"y":909,"w":128,"h":151,"ax":944,"ay":702},"m2":{"x":417,"y":900,"w":121,"h":165,"ax":548,"ay":702},"m3":{"x":522,"y":898,"w":114,"h":150,"ax":1074,"ay":702},"m4":{"x":617,"y":889,"w":105,"h":149,"ax":1190,"ay":702},"m5":{"x":708,"y":875,"w":122,"h":143,"ax":1431,"ay":702},"m6":{"x":809,"y":864,"w":164,"h":179,"ax":382,"ay":702},"d0":{"x":250,"y":1059,"w":206,"h":221,"ax":1147,"ay":0},"d1":{"x":447,"y":1054,"w":141,"h":157,"ax":801,"ay":702},"d2":{"x":571,"y":1038,"w":128,"h":161,"ax":671,"ay":702},"d3":{"x":683,"y":1023,"w":171,"h":182,"ax":209,"ay":702},"bolt":{"x":336,"y":1195,"w":486,"h":91,"ax":589,"ay":915},"g0":{"x":185,"y":1306,"w":133,"h":32,"ax":0,"ay":1040},"g1":{"x":347,"y":1286,"w":64,"h":69,"ax":1217,"ay":915},"g2":{"x":429,"y":1287,"w":64,"h":67,"ax":1344,"ay":915},"g3":{"x":514,"y":1288,"w":81,"h":66,"ax":1410,"ay":915},"g4":{"x":614,"y":1287,"w":60,"h":66,"ax":1493,"ay":915},"g5":{"x":692,"y":1286,"w":59,"h":68,"ax":1283,"ay":915},"g6":{"x":759,"y":1303,"w":138,"h":32,"ax":135,"ay":1040},"shadow":{"x":216,"y":790,"w":481,"h":123,"ax":0,"ay":915},"mfill":{"x":246,"y":109,"w":792,"h":700,"ax":0,"ay":0},"mk1":{"x":954,"y":114,"w":132,"h":146,"ax":1297,"ay":702},"mk2":{"x":184,"y":378,"w":66,"h":76,"ax":1149,"ay":915},"mk3":{"x":976,"y":470,"w":70,"h":86,"ax":1077,"ay":915}},"AW":1600,"AH":1072};
  var SRC=["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"];
  var W=M.W,H=M.H,IT=M.items,DONE_AT=3800,HOLD=500;
  var reduced=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var root=document.createElement('div'),cv=document.createElement('canvas'),ctx=cv.getContext('2d');
  var dpr=1,sc=1,ox=0,oy=0,start=0,V=0,ready=false,ended=false,raf=0,shown=performance.now(),seenW=0,seenH=0;
  var atl=[],SEQ=[0,1,2,1,0,2,0,1,2,0,2,1];
  var resolveDone,api=window.GameSplash={playing:true,duration:DONE_AT+HOLD,done:new Promise(function(r){resolveDone=r;}),skip:function(){finish(true);}};

  function clamp(v){return v<0?0:v>1?1:v;}
  function easeIn(t){return t*t;}
  function easeOut(t){return 1-(1-t)*(1-t);}
  function easeInOut(t){return t<0.5?2*t*t:1-Math.pow(-2*t+2,2)/2;}
  function easeOutBack(t){var c=1.70158;return 1+(c+1)*Math.pow(t-1,3)+c*Math.pow(t-1,2);}
  function lerp(a,b,t){return a+(b-a)*t;}

  function item(n){var i=IT[n];ctx.drawImage(atl[V],i.ax,i.ay,i.w,i.h,i.x,i.y,i.w,i.h);}
  /* dessine un calque agrandi/écrasé autour d'un point fixe */
  function scaled(n,px,py,sx,sy){
    if(sx<=0||sy<=0)return;
    ctx.save();ctx.translate(px,py);ctx.scale(sx,sy);ctx.translate(-px,-py);item(n);ctx.restore();
  }
  /* révèle un calque de gauche à droite */
  function wipe(n,p){
    if(p<=0)return;var i=IT[n];
    ctx.save();ctx.beginPath();ctx.rect(i.x,i.y,i.w*p,i.h);ctx.clip();item(n);ctx.restore();
  }

  /* ---------- Le canard : chute, écrasement, cape qui ondule ---------- */
  var FEET_X=330,FEET_Y=886,CAPE_X=262,DKX=-36,DKY=14;
  var HATCH=1050,S=400;
  function J(seed){var x=Math.sin(seed*12.9898+V*78.233)*43758.5453;return (x-Math.floor(x))-0.5;}
  /* ---------- L'œuf : il tombe, s'écrase, se fendille, puis éclate ---------- */
  var ERX=74,ERY=96,ZY=-104;
  function eggPath(seed){
    ctx.beginPath();
    for(var i=0;i<26;i++){
      var a=i/26*Math.PI*2,sn=Math.sin(a);
      var x=Math.cos(a)*ERX*(1+0.12*sn)+J(seed+i)*3,y=-ERY+sn*ERY+J(seed+i+0.5)*3;
      if(i)ctx.lineTo(x,y);else ctx.moveTo(x,y);
    }
    ctx.closePath();
  }
  function zig(i){return [-90+i*20,ZY+(i%2?-14:13)];}
  function halfClip(top,x0,x1){
    ctx.beginPath();
    ctx.moveTo(x0,top?-400:200);
    for(var i=0;i<=9;i++){var z=zig(i);ctx.lineTo(Math.max(x0,Math.min(x1,z[0])),z[1]);}
    ctx.lineTo(x1,top?-400:200);ctx.closePath();ctx.clip();
  }
  function shellPiece(tau,vx,vy,spin,top,x0,x1,seed){
    var al=1-clamp((tau-380)/260);if(al<=0)return;
    ctx.save();ctx.globalAlpha=al;
    ctx.translate(vx*tau,vy*tau+0.0016*tau*tau);
    ctx.translate(0,ZY);ctx.rotate(spin*tau);ctx.translate(0,-ZY);
    halfClip(top,x0,x1);eggPath(seed);ctx.fillStyle='#FCEFD4';ctx.fill();
    ctx.restore();
  }
  function drawEgg(t){
    if(t<300||t>HATCH+700)return;
    var bx=FEET_X+DKX,by=FEET_Y+DKY-4;
    ctx.save();ctx.translate(bx,by);
    if(t<HATCH){
      var tf=clamp((t-300)/350),yOff=-(1-tf*tf)*1000,sy=1,rot=0;
      if(t<650)sy=1+0.22*tf;
      else if(t<692)sy=0.7;
      else if(t<733)sy=0.87;
      else if(t<800)sy=1+0.05*Math.sin(Math.PI*(t-733)/67);
      /* il se dandine de plus en plus fort avant d'éclater */
      if(t>=800){var w=(t-800)/(HATCH-800);rot=0.2*w*Math.sin((t-800)/30);sy=1+0.04*w*Math.sin((t-800)/22);}
      ctx.translate(0,yOff);ctx.rotate(rot);ctx.scale(Math.pow(sy,-0.6),sy);
      eggPath(50);ctx.fillStyle='#FCEFD4';ctx.fill();
      var cp=clamp((t-800)/200);
      if(cp>0){
        ctx.strokeStyle='#16100B';ctx.lineWidth=5;ctx.lineJoin='round';ctx.lineCap='round';
        ctx.beginPath();
        var n=cp*9;
        for(var i=1;i<=8&&i<=n+1;i++){
          var z=zig(i),zp=zig(i-1),f=Math.min(1,n-(i-1));if(f<=0)break;
          if(i===1)ctx.moveTo(zp[0]+22,zp[1]+4);
          ctx.lineTo(zp[0]+(z[0]-zp[0])*f,zp[1]+(z[1]-zp[1])*f);
        }
        ctx.stroke();
      }
    }else{
      var tau=t-HATCH;
      shellPiece(tau,0.42,-1.05,0.007,true,-200,200,50);
      shellPiece(tau,-0.62,-0.42,-0.006,false,-200,0,50);
      shellPiece(tau,0.66,-0.36,0.006,false,0,200,50);
      /* petits éclats */
      ctx.fillStyle='#FCEFD4';
      var FR=[[-0.5,-0.9],[0.25,-1.2],[-0.2,-1.3],[0.75,-0.75],[-0.85,-0.6]];
      for(var k=0;k<FR.length;k++){
        var al=1-clamp((tau-300)/250);if(al<=0)break;
        var px=FR[k][0]*tau,py=ZY+FR[k][1]*tau+0.0019*tau*tau;
        ctx.save();ctx.globalAlpha=al;ctx.translate(px,py);ctx.rotate(tau*0.012*(k%2?1:-1));
        ctx.beginPath();ctx.moveTo(-9,6);ctx.lineTo(0,-10);ctx.lineTo(10,7);ctx.closePath();ctx.fill();ctx.restore();
      }
    }
    ctx.restore();
    /* poussière quand l'œuf touche le sol */
    var te=t-650;
    if(te>=0&&te<350){
      var e=easeOut(te/350);
      ctx.save();ctx.globalAlpha=1-te/350;ctx.strokeStyle='#FCEFD4';ctx.lineWidth=8;ctx.lineCap='round';
      ctx.beginPath();
      ctx.moveTo(bx-90-40*e,by-4);ctx.lineTo(bx-116-52*e,by-22-10*e);
      ctx.moveTo(bx+90+40*e,by-4);ctx.lineTo(bx+116+52*e,by-22-10*e);
      ctx.stroke();ctx.restore();
    }
  }

  /* ---------- Le canard jaillit de l'œuf, cape en retard ---------- */
  function drawDuck(t){
    if(t<HATCH)return;
    var d=IT.duck,tau=t-HATCH;
    var pop=easeOutBack(clamp(tau/170));
    var sy=tau<260?1+0.18*(1-tau/260):1+0.006*Math.sin(t/600);
    var sx=Math.pow(sy,-0.6);
    var lift=-70*Math.exp(-tau/200)*Math.cos(tau/100),gain=1+1.6*Math.exp(-tau/350);
    ctx.save();
    ctx.translate(FEET_X+DKX,FEET_Y+DKY);ctx.scale(sx*pop,sy*pop);ctx.translate(-FEET_X,-FEET_Y);
    var cw=CAPE_X-d.x,STEP=3,a=atl[V];
    for(var s=0;s<cw;s+=STEP){
      var u=1-s/cw,k=Math.pow(u,1.3);
      var dy=reduced?0:k*(11*gain*Math.sin(t*0.0085-u*3.2)+lift);
      var w=Math.min(STEP,cw-s);
      ctx.drawImage(a,d.ax+s,d.ay,w,d.h,d.x+s,d.y+dy,w+0.6,d.h);
    }
    ctx.drawImage(a,d.ax+cw,d.ay,d.w-cw,d.h,d.x+cw,d.y,d.w-cw,d.h);
    /* clignement */
    if(!reduced&&t>1900&&((t-1900)%3400)<130){
      for(var e=0;e<M.eyes.length;e++){
        var ey=M.eyes[e];
        ctx.fillStyle='#FCEFD4';ctx.beginPath();ctx.ellipse(ey[0],ey[1],ey[2]*0.5+4,ey[3]*0.5+4,0,0,7);ctx.fill();
        ctx.strokeStyle='#16100B';ctx.lineWidth=5;ctx.lineCap='round';
        ctx.beginPath();ctx.moveTo(ey[0]-8,ey[1]+3);ctx.lineTo(ey[0]+8,ey[1]+1);ctx.stroke();
      }
    }
    ctx.restore();
  }

  /* ---------- L'ombre au sol puis le costaud sur le mur ---------- */
  function drawShadow(t){
    if(t<1050)return;
    var p=1;
    var fx=300+DKX,fy=872+DKY;
    ctx.save();
    ctx.translate(fx,fy);ctx.scale(p,0.6+0.4*p);ctx.translate(-fx,-fy);
    item('shadow');ctx.restore();
  }
  function drawMuscle(t){
    if(t<1050)return;
    var sx=1,sy=1;
    var punch=0;
    if(t>=1650){var q=t-1650;punch=q<90?0.07*easeOut(q/90):0.07*Math.exp(-(q-90)/160);}
    var br=t>2100&&!reduced?0.012*Math.sin((t-2100)/520):0;
    scaled('mfill',590,801,sx*(1+punch-br*0.6),sy*(1+punch*0.6+br));
    if(t>=1650){
      var pk=easeOutBack(clamp((t-1650)/150));
      /* petits traits de mouvement : ils jaillissent à la contraction puis frémissent avec les muscles */
      var th=reduced?0:0.05*Math.sin((t-1650)/130)*Math.exp(-(t-1650)/900)+0.03*Math.sin((t-2100)/520);
      scaled('mticks',330,270,pk,pk);
      scaled('mk1',930,270,pk*(1+th),pk*(1+th));
      scaled('mk2',300,420,pk*(1+th),pk*(1+th));
      scaled('mk3',940,500,pk*(1+th),pk*(1+th));
    }
  }

  /* ---------- Titre : les vraies lettres du visuel, qui claquent une par une ---------- */
  function slam(n,tau){
    if(tau<0)return;
    var i=IT[n],s=1,al=1;
    if(tau<120){s=2.4-1.4*easeIn(tau/120);al=tau/120;}
    else if(tau<200){s=1-0.08*Math.sin(Math.PI*(tau-120)/80);}
    ctx.save();ctx.globalAlpha=al;
    var cx=i.x+i.w/2,cy=i.y+i.h/2;
    ctx.translate(cx,cy);ctx.scale(s,s);ctx.translate(-cx,-cy);item(n);ctx.restore();
  }
  function drawTitle(t){
    var k;
    for(k=0;k<7;k++)slam('m'+k,t-(1850+k*55));
    for(k=0;k<4;k++)slam('d'+k,t-(2400+k*70));
    wipe('bolt',clamp((t-2780)/150));
    var g=easeOut(clamp((t-2950)/250));
    if(g>0){
      ctx.save();ctx.globalAlpha=g;ctx.translate(0,(1-g)*18);
      for(k=0;k<7;k++)if(IT['g'+k])item('g'+k);
      ctx.restore();
    }
  }

  var SHAKES=[[650,3],[1050,5],[2050,3],[2370,2],[2920,4]];
  function shakeAt(t){
    var a=0;
    for(var i=0;i<SHAKES.length;i++){var d=t-SHAKES[i][0];if(d>=0&&d<300)a+=SHAKES[i][1]*Math.exp(-d/60);}
    return a;
  }

  function draw(t,now){
    V=reduced?0:SEQ[Math.floor(now/125)%SEQ.length];
    ctx.setTransform(1,0,0,1,0,0);
    var cxp=cv.width/2,cyp=cv.height*0.42,R=Math.max(cv.width,cv.height)*0.75;
    var gr=ctx.createRadialGradient(cxp,cyp,0,cxp,cyp,R);
    gr.addColorStop(0,'rgb(207,4,17)');gr.addColorStop(1,'rgb(188,2,12)');
    ctx.fillStyle=gr;ctx.fillRect(0,0,cv.width,cv.height);
    if(!ready)return;
    var sh=reduced?0:shakeAt(t);
    var dx=sh?(Math.random()*2-1)*sh:0,dy=sh?(Math.random()*2-1)*sh:0;
    ctx.setTransform(dpr*sc,0,0,dpr*sc,dpr*(ox+dx*sc),dpr*(oy+dy*sc));
    /* toute l'ombre sort du canard : elle grandit d'un seul tenant depuis ses pieds */
    var ts=t-S;
    if(ts>=1050){
      var u=clamp((ts-1050)/480),c=0.9,g=1+(c+1)*Math.pow(u-1,3)+c*Math.pow(u-1,2);
      var fx=300+DKX,fy=872+DKY;
      ctx.save();ctx.translate(fx,fy);ctx.scale(g,g);ctx.translate(-fx,-fy);
      drawMuscle(ts);drawShadow(ts);
      ctx.restore();
    }
    drawEgg(t);
    drawDuck(t);
    if(t-S>=900){var p=easeOutBack(clamp((t-S-900)/150));ctx.save();ctx.translate(DKX,DKY);scaled('dticks',330,680,p,p);ctx.restore();}
    drawTitle(t-S);
  }

  function resize(){
    dpr=Math.min(window.devicePixelRatio||1,2);
    var w=window.innerWidth,h=window.innerHeight;
    seenW=w;seenH=h;
    cv.width=Math.round(w*dpr);cv.height=Math.round(h*dpr);
    sc=Math.min(w/W,h/H);ox=(w-W*sc)/2;oy=(h-H*sc)/2;
    if(ready&&reduced)draw(99999,0);
  }
  function finish(fast){
    if(ended)return;
    ended=true;api.playing=false;
    cancelAnimationFrame(raf);window.removeEventListener('resize',resize);
    var ms=fast?180:350;
    root.style.transition='opacity '+ms+'ms ease';root.style.opacity='0';root.style.pointerEvents='none';
    setTimeout(function(){
      if(root.parentNode)root.parentNode.removeChild(root);
      atl.length=0;
      resolveDone();
      try{window.dispatchEvent(new CustomEvent('musclor-splash:done'));}catch(e){}
    },ms+20);
  }
  function frame(now){
    if(ended)return;
    // A page read from its <head> may not know its real size yet (viewport tag not read): follow it.
    if(window.innerWidth!==seenW||window.innerHeight!==seenH)resize();
    var t=Math.max(0,now-start);
    try{draw(t,now);}catch(e){finish(true);return;}
    if(t>=DONE_AT+HOLD){finish(false);return;}
    raf=requestAnimationFrame(frame);
  }
  function go(){
    ready=true;start=performance.now();
    if(reduced){try{draw(99999,0);}catch(e){}setTimeout(function(){finish(false);},1200);return;}
    raf=requestAnimationFrame(frame);
    setTimeout(function(){finish(false);},DONE_AT+HOLD+4000);  // a hidden tab stops the frames: leave anyway
  }

  root.setAttribute('aria-hidden','true');
  root.style.cssText='position:fixed;left:0;top:0;width:100vw;height:100vh;height:100dvh;z-index:2147483000;background:#C8040F;touch-action:none;-webkit-user-select:none;user-select:none';
  cv.style.cssText='display:block;width:100%;height:100%';
  root.appendChild(cv);
  // The opening keeps every touch and key for itself, so nothing reaches the game underneath; a tap ends it.
  ['pointerdown','pointerup','click','touchstart','touchend','mousedown','mouseup'].forEach(function(n){
    root.addEventListener(n,function(e){
      e.stopPropagation();if(e.cancelable)e.preventDefault();
      if(n==='pointerdown'&&performance.now()-shown>500)finish(true);
    },{passive:false});
  });
  (document.body||document.documentElement).appendChild(root);
  window.addEventListener('resize',resize);
  resize();
  try{draw(0,0);}catch(e){}

  var left=SRC.length;
  SRC.forEach(function(src,i){
    var im=new Image();
    im.onload=function(){left--;if(left===0&&!ended)go();};
    im.onerror=function(){finish(true);};
    im.src=src;atl[i]=im;
  });
  setTimeout(function(){if(!ready)finish(true);},3000);
})();
